from solution import group_anagrams


def test_group_anagrams():
    got = {frozenset(g) for g in group_anagrams(["eat", "tea", "tan", "ate", "nat", "bat"])}
    want = {frozenset({"eat", "tea", "ate"}), frozenset({"tan", "nat"}), frozenset({"bat"})}
    assert got == want
    assert group_anagrams([]) == []
